"use client";
/**
 * Download button for a PDF generated by the API.
 *   <PdfButton path={orgUrl(orgSlug, `leave/requests/${id}/export.pdf`)} fileName="conge.pdf" label="PDF" />
 */
import { useState } from "react";
import { FileDown } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { api } from "@/lib/api";

export async function downloadPdf(path: string, fileName: string, params?: Record<string, unknown>) {
  const response = await api.get(path, { responseType: "blob", params, timeout: 120_000 });
  const blob = new Blob([response.data], { type: "application/pdf" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName.endsWith(".pdf") ? fileName : `${fileName}.pdf`;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 2_000);
}

async function blobError(error: unknown) {
  const data = (error as { response?: { data?: unknown } })?.response?.data;
  if (data instanceof Blob) {
    try {
      const parsed = JSON.parse(await data.text()) as { error?: { message?: string } };
      return parsed.error?.message ?? "";
    } catch {
      return "";
    }
  }
  return error instanceof Error ? error.message : "";
}

export function PdfButton({
  path,
  fileName,
  label = "PDF",
  params,
  size = "sm",
  variant = "outline",
  className,
}: {
  path: string;
  fileName: string;
  label?: string;
  params?: Record<string, unknown>;
  size?: "sm" | "md" | "icon-sm";
  variant?: "outline" | "ghost" | "secondary" | "primary";
  className?: string;
}) {
  const [loading, setLoading] = useState(false);
  return (
    <Button
      type="button"
      size={size}
      variant={variant}
      className={className}
      loading={loading}
      onClick={async (event) => {
        event.stopPropagation();
        setLoading(true);
        try {
          await downloadPdf(path, fileName, params);
        } catch (error) {
          toast.error((await blobError(error)) || "Le PDF n’a pas pu être créé.");
        } finally {
          setLoading(false);
        }
      }}
    >
      <FileDown className="size-4" />
      {size === "icon-sm" ? null : label}
    </Button>
  );
}
